const ketikan: [number, string][] = [[0, "s"], [120, "se"], [250, "sep"], [900, "sepa"], [1000, "sepat"], [1100, "sepatu"]];
for (let t = 0; t <= 2000; t += 50) {
  const k = ketikan.find(([w]) => w === t); if (k) s.ketik(...k);
